export const SCHEMA=4;
export const clamp=(n,a,b)=>Math.min(b,Math.max(a,n));
export const uid=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);
export function randomSeed(){return globalThis.crypto?.getRandomValues?.(new Uint32Array(1))[0]??Math.floor(Math.random()*4294967295)}
export function seeded(seed){let a=Number(seed)>>>0;return()=>{a+=0x6d2b79f5;let t=a;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return((t^t>>>14)>>>0)/4294967296}}
const pick=(a,r)=>a[Math.floor(r()*a.length)];
export const classOf=h=>CLASSES.find(c=>c.id===h.classId)||CLASSES[0];
export const raceOf=h=>RACES.find(r=>r.id===h.raceId)||RACES[0];
export const townOf=h=>h.world.towns.find(t=>t.id===h.location.townId)||h.world.towns[0];
export const BUILDINGS=[
 {id:'inn',role:'innkeeper',name:'The Wayfarer’s Rest',x:-10.7,z:11,description:'A hearth, a hot meal, and stories that grow stranger after sunset.'},
 {id:'smith',role:'smith',name:'The Ember & Anvil',x:10.7,z:7,description:'The forge burns orange. Half-finished blades hang above the workbench.'},
 {id:'archive',role:'scholar',name:'The Lantern Archive',x:-10.7,z:-9,description:'Dusty shelves surround a reading table scattered with impossible maps.'},
 {id:'apothecary',role:'healer',name:'The Stillwater Apothecary',x:10.7,z:-12,description:'Dried herbs sway over shelves of glass bottles and a clean infirmary bed.'},
 {id:'chapel',role:'warden',name:'The Watch Chapel',x:0,z:-30.8,description:'Colored light crosses the stone aisle. The watch keeps its old vows here.'}
];
export const buildingOf=h=>h.location.room==='home'?{...homePlan(townOf(h))[h.location.homeId],id:'home'}:BUILDINGS.find(b=>b.id===h.location.room);
export const locationId=h=>h.location.type+'-'+h.location.townId+(h.location.type==='interior'?'-'+h.location.room+(h.location.room==='home'?'-'+h.location.homeId:''):'');
export function addLog(h,text,kind='story'){h.history.unshift({id:uid(),text:String(text).slice(0,2000),kind,day:h.world?.day||1});h.history=h.history.slice(0,160);h.updatedAt=Date.now();return text}
export function effects(h){const out={...factionEffects(h)};for(const entry of[...(h.world?.blessings||[]).map(b=>BLESSINGS.find(x=>x.id===b.id)),...patronage(h).filter(p=>p.earned)])if(entry)for(const[k,v]of Object.entries(entry.effect))out[k]=(out[k]||0)+v;for(const id of h.talents){const t=classOf(h).talents.find(t=>t.id===id);if(t)for(const[k,v]of Object.entries(t.effect))out[k]=(out[k]||0)+v}return out}
export function stats(h){const s={...classOf(h).stats};for(const[k,v]of Object.entries(raceOf(h).stats))s[k]=(s[k]||0)+v;const o=ORIGINS.find(o=>o.id===h.originId);if(o)s[o.stat]++;const e=effects(h);for(const k of Object.keys(s))s[k]+=(e[k]||0)+Math.floor((h.level-1)/3);return s}
export function maxHp(h){return classOf(h).hp+(h.raceId==='dwarf'?8:0)+(h.level-1)*6+(h.boons?.vitality||0)}
export function maxMp(h){return classOf(h).mp+(h.raceId==='elf'?6:0)+(h.level-1)*3}
export function armor(h){return(h.equipment.armor?.power||0)+(effects(h).defense||0)}
export function abilityCost(h){return Math.max(2,classOf(h).ability.cost-(effects(h).cost||0)-(h.raceId==='exile'?1:0))}
export function xpNeeded(h){return 80+(h.level-1)*45}
export function gainXp(h,n){h.xp+=Math.max(0,n);let levels=0;while(h.xp>=xpNeeded(h)){h.xp-=xpNeeded(h);h.level++;h.talentPoints++;h.hp=Math.min(maxHp(h),h.hp+16);h.mp=Math.min(maxMp(h),h.mp+9);levels++;addLog(h,`Level ${h.level}. Your legend grows. +1 talent point.`,'level')}return levels}
export function gainGold(h,n){h.gold+=Math.floor(n*(1+(effects(h).gold||0)/100))}
export function tradePrice(h,base,role='smith',name=''){
 const reputation=Math.max(0,h.factions[role==='stranger'?'veil':'town']||0),friendship=Math.max(0,h.relationships[name]||0),discount=Math.min(.25,reputation*.015+friendship*.002);return Math.max(1,Math.ceil(base*(1-discount)));
}
export function check(h,stat,dc,rng=Math.random){const roll=1+Math.floor(rng()*20),bonus=(stats(h)[stat]||0)+(effects(h).checks||0)+(h.raceId==='fae'?1:0);return{roll,bonus,total:roll+bonus,dc,success:roll===20||(roll!==1&&roll+bonus>=dc)}}
export function makeHero(draft,seed=randomSeed()){
 const h={schema:SCHEMA,id:uid(),name:String(draft.name||'Wanderer').trim().slice(0,32)||'Wanderer',classId:CLASSES.some(c=>c.id===draft.classId)?draft.classId:'ranger',raceId:RACES.some(r=>r.id===draft.raceId)?draft.raceId:'human',originId:ORIGINS.some(o=>o.id===draft.originId)?draft.originId:'wanderer',omen:String(draft.omen||'Your shadow sometimes moves without you.').slice(0,200),backstory:String(draft.backstory||'').slice(0,600),portrait:clamp(Number(draft.portrait)||0,0,7),...appearanceOf(draft),level:1,xp:0,talentPoints:(draft.raceId==='human'?3:2),talents:[],gold:75,hp:1,mp:1,boons:{},items:[],equipment:{},history:[],legacy:[],completed:0,kills:0,playSeconds:0,createdAt:Date.now(),updatedAt:Date.now(),relationships:{},factions:{town:0,scholars:0,veil:0},settings:{},combat:null};
 h.equipment={weapon:{id:uid(),name:classOf(h).weapon,type:'weapon',power:3,quality:0},armor:{id:uid(),name:'Traveler’s Attire',type:'armor',power:1,quality:0}};
 h.items=[{id:uid(),name:'Healing Draught',type:'potion',qty:4},{id:uid(),name:'Moonwater',type:'mana',qty:2}];h.hp=maxHp(h);h.mp=maxMp(h);newCampaign(h,seed);return h;
}
export function generateDungeon(seed){
 const r=seeded(seed),size=17,grid=Array.from({length:size},()=>Array(size).fill(1)),stack=[[1,1]];grid[1][1]=0;
 while(stack.length){const[x,y]=stack[stack.length-1];const choices=[[2,0],[-2,0],[0,2],[0,-2]].filter(([dx,dy])=>x+dx>0&&y+dy>0&&x+dx<size-1&&y+dy<size-1&&grid[y+dy][x+dx]);if(!choices.length){stack.pop();continue}const[dx,dy]=pick(choices,r);grid[y+dy/2][x+dx/2]=0;grid[y+dy][x+dx]=0;stack.push([x+dx,y+dy])}
 // Open a few loops, then use breadth-first distance so the final chamber is reachable.
 for(let i=0;i<16;i++){const x=1+Math.floor(r()*(size-2)),y=1+Math.floor(r()*(size-2));if((!grid[y][x-1]&&!grid[y][x+1])||(!grid[y-1][x]&&!grid[y+1][x]))grid[y][x]=0}
 const dist=Array.from({length:size},()=>Array(size).fill(-1)),q=[[1,1]];dist[1][1]=0;
 for(let i=0;i<q.length;i++){const[x,y]=q[i];for(const[dx,dy]of[[1,0],[-1,0],[0,1],[0,-1]])if(grid[y+dy]?.[x+dx]===0&&dist[y+dy][x+dx]<0){dist[y+dy][x+dx]=dist[y][x]+1;q.push([x+dx,y+dy])}}
 const ordered=q.slice().sort((a,b)=>dist[b[1]][b[0]]-dist[a[1]][a[0]]),end=ordered[0];
 const candidates=q.filter(([x,y])=>dist[y][x]>5&&Math.abs(x-end[0])+Math.abs(y-end[1])>2);
 const spots=[];for(let i=0;i<9&&candidates.length;i++){const k=Math.floor(r()*candidates.length);spots.push(candidates.splice(k,1)[0])}
 const entities=[{id:'exit',type:'exit',name:'Return to the surface',x:6,z:6},{id:'boss',type:'boss',name:'The guardian',x:end[0]*4+2,z:end[1]*4+2}];
 spots.forEach(([x,y],i)=>{const foe=pick(ENEMIES,r);entities.push({id:'crypt-'+i,type:i<4?'enemy':i<7?'chest':i===7?'shrine':'lore',name:i<4?foe.name:i<7?'Sealed coffer':i===7?'Moonlit shrine':'Ancient inscription',kind:foe.kind,x:x*4+2,z:y*4+2})});
 return{grid,entities,end,start:{x:6,z:6,yaw:grid[1][2]===0?Math.PI/2:0},seen:[]};
}
export function newCampaign(h,seed=randomSeed()){
 const r=seeded(seed),used=h.legacy.map(v=>v.motifId),available=MOTIFS.filter(m=>!used.includes(m.id));let motif=structuredClone(pick(available.length?available:MOTIFS.filter(m=>m.id!==h.campaign?.motifId),r));
 const names=new Set(),npcNames=new Set();const climates=['green','autumn','mist'],climateOffset=Math.floor(r()*3);const towns=[];for(let i=0;i<3;i++){let name;do{name=pick(SETTLEMENT_PREFIX,r)+pick(SETTLEMENT_SUFFIX,r)}while(names.has(name));names.add(name);const npcs={};for(const role of['innkeeper','smith','scholar','warden','healer','witness','stranger']){let npcName;do{npcName=pick(NPC_FIRST,r)+' '+pick(NPC_LAST,r)}while(npcNames.has(npcName));npcNames.add(npcName);npcs[role]={id:`${i}-${role}`,name:npcName,role,portrait:Math.floor(r()*8)}};towns.push({id:i,name,seed:Math.floor(r()*1e9),climate:climates[(i+climateOffset)%3],npcs,description:['A river village caught between the old woods and an older secret.','Amber leaves gather around a hilltop settlement of miners and itinerant scholars.','A trading town at the edge of a marsh where the lanterns never go out.'][(i+climateOffset)%3],dungeon:generateDungeon(Math.floor(r()*1e9))})}
 h.campaign={...motif,id:uid(),number:h.completed+1,motifId:motif.id,stage:'arrival',flags:{},decisions:[],ai:false,startedAt:Date.now(),ending:null};
 h.world={seed,towns,day:1,hour:17,visits:{},rumors:[],quests:[],events:[],claimed:[],ledger:{},discovered:['town-0'],weather:pick(['clear','mist','rain'],r)};h.location={type:'town',townId:0};h.position={x:0,z:20,yaw:Math.PI};h.combat=null;delete h.companion;h.summonCooldown=0;
 upgradeHero(h);addLog(h,`A new adventure: ${motif.title}. You arrive in ${towns[0].name}. ${h.omen}`);return h.campaign;
}
export function upgradeHero(h){
 Object.assign(h,appearanceOf(h));delete h.pronouns;
 if(h.world.towns.length===3){const r=seeded(h.world.seed^0x61b9a203),names=new Set(h.world.towns.map(t=>t.name));for(let id=3;id<REGION_COUNT;id++){let name;do{name=pick(SETTLEMENT_PREFIX,r)+pick(SETTLEMENT_SUFFIX,r)}while(names.has(name));names.add(name);const npcs={};for(const role of['innkeeper','smith','scholar','warden','healer','witness','stranger'])npcs[role]={id:`${id}-${role}`,name:pick(NPC_FIRST,r)+' '+pick(NPC_LAST,r),role,portrait:Math.floor(r()*8)};const region=regionOf({id});h.world.towns.push({id,name,seed:Math.floor(r()*1e9),climate:region.climate,npcs,description:region.detail,dungeon:generateDungeon(Math.floor(r()*1e9))})}}
 h.world.expansion=1;h.world.exploration??={sites:[],rewards:[]};return h;
}
export function surveyLandmark(h,id,method='study',rng=Math.random){
 const site=(h.location.type==='wilds'||h.location.type==='realm')&&frontierSites(townOf(h)).find(s=>s.id===id);if(!site)return{ok:false,text:'Find this place in the wilderness first.'};const key=siteKey(h,id);h.world.exploration??={sites:[],rewards:[]};if(h.world.exploration.sites.includes(key))return{ok:false,text:'Your journal already records what you found here.'};if(!['study','restore','salvage'].includes(method))return{ok:false,text:'Choose how to approach the site.'};if(method==='restore'&&h.gold<12)return{ok:false,text:'You need 12 gold in supplies.'};
 const roll=method==='study'?check(h,site.stat,h.world.exploration?.charted?.includes(h.location.townId)?9:11,rng):null,success=!roll||roll.success;h.world.exploration.sites.push(key);gainXp(h,success?28:12);let text=success?'You uncover the site’s story and add it to your survey.':'The site keeps its deepest secret. Your survey still records a safe route here.';let item=null;
 if(method==='restore'){h.gold-=12;h.factions.town++;h.hp=Math.min(maxHp(h),h.hp+8);text+=' You repair the ward and leave supplies. The townsfolk will hear of it.'}
 if(success){gainGold(h,method==='salvage'?24:12);if(['tower','mine','ruin','bridge'].includes(site.kind)){const visual={tower:'spear',mine:'axe',ruin:'staff',bridge:'dagger'}[site.kind];item={id:uid(),type:'weapon',name:{tower:'Watchkeeper’s Spear',mine:'Quarryman’s Veilsteel Axe',ruin:'Astronomer’s Moonstaff',bridge:'Ferryman’s Dagger'}[site.kind],visual,power:5+h.level*2,quality:1};h.items.push(item)}else if(site.kind==='camp'||site.kind==='stones'){item={id:uid(),type:'armor',name:site.kind==='camp'?'Wayfarer’s Leather Armor':'Circlekeeper’s Mantle',visual:site.kind==='camp'?'leather':'cloth',power:3+h.level,quality:1};h.items.push(item)}else h.items.push({id:uid(),type:'potion',name:'Healing Draught',qty:1});if(item)text+=' Recovered '+item.name+'. Equip it from your satchel.'}
 const survey=surveyState(h);if(survey.done===survey.total&&!survey.claimed){h.world.exploration.rewards.push(h.location.townId);gainGold(h,120);gainXp(h,80);text+=' Region surveyed: +120 gold and +80 XP.'}if(roll)text+=` D20 ${roll.roll} + ${roll.bonus} against ${roll.dc}.`;addLog(h,site.name+': '+text,'discovery');return{ok:true,text,item,success};
}
export function locationName(h){const t=townOf(h);if(h.location.type==='realm'&&h.location.area==='wilds')return t.name+' · Wilds';return h.location.type==='interior'?buildingOf(h)?.name||t.name:['town','realm'].includes(h.location.type)?t.name:h.location.type==='wilds'?`The ${t.name} Road`:`${t.name} Undercrypt`}
export function objective(h){const t=h.world.towns[0],c=h.campaign;if(h.combat)return'Defeat your foe or find a way out.';if(c.stage==='arrival')return`Speak with ${t.npcs.witness.name} in ${t.name}’s square.`;if(c.stage==='trail')return`Investigate the strange remains on the road outside ${t.name}.`;if(c.stage==='counsel')return`Bring the evidence to ${t.npcs.scholar.name} at ${t.name}’s archive.`;if(c.stage==='descent')return`Enter the undercrypt outside ${t.name}. Find ${c.enemy}.`;if(c.stage==='heart')return`Return to the final chamber and decide the fate of ${c.artifact}.`;return'Your adventure is complete. Explore, or set out on a new story.'}
export function visitState(h){const id=locationId(h);return h.world.visits[id]??={resolved:[],discovered:[],searched:false}}
export function resolveEntity(h,id){const v=visitState(h);if(!v.resolved.includes(id))v.resolved.push(id)}
export function isResolved(h,id){return visitState(h).resolved.includes(id)}
